CREATE TABLE public.talent_profiles(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,work_experience text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.talent_profiles TO authenticated; GRANT SELECT ON public.talent_profiles TO anon; GRANT ALL ON public.talent_profiles TO service_role; ALTER TABLE public.talent_profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY talent_details_read ON public.talent_profiles FOR SELECT USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=user_id AND p.shared) OR public.has_role(auth.uid(),'admin')); CREATE POLICY talent_details_write ON public.talent_profiles FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.employer_profiles(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,company_name text NOT NULL,website text NOT NULL DEFAULT '',description text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.employer_profiles TO authenticated; GRANT SELECT ON public.employer_profiles TO anon; GRANT ALL ON public.employer_profiles TO service_role; ALTER TABLE public.employer_profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY companies_read ON public.employer_profiles FOR SELECT USING(true); CREATE POLICY companies_own ON public.employer_profiles FOR ALL TO authenticated USING(user_id=auth.uid() AND public.has_role(auth.uid(),'employer')) WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'employer'));
CREATE TABLE public.skills(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE); GRANT SELECT ON public.skills TO anon,authenticated; GRANT ALL ON public.skills TO service_role; ALTER TABLE public.skills ENABLE ROW LEVEL SECURITY; CREATE POLICY skill_read ON public.skills FOR SELECT USING(true); INSERT INTO public.skills(name) VALUES('React'),('TypeScript'),('CSS'),('Python'),('Excel'),('Communication'),('Accounting'),('Administration'),('Customer service');
CREATE TABLE public.talent_skills(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,skill_id uuid NOT NULL REFERENCES public.skills(id),status text NOT NULL DEFAULT 'Self-reported' CHECK(status='Self-reported'),PRIMARY KEY(user_id,skill_id)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.talent_skills TO authenticated; GRANT ALL ON public.talent_skills TO service_role; ALTER TABLE public.talent_skills ENABLE ROW LEVEL SECURITY; CREATE POLICY talent_skills_own ON public.talent_skills FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.portfolio_projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,title text NOT NULL,description text NOT NULL,url text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.portfolio_projects TO authenticated; GRANT SELECT ON public.portfolio_projects TO anon; GRANT ALL ON public.portfolio_projects TO service_role; ALTER TABLE public.portfolio_projects ENABLE ROW LEVEL SECURITY; CREATE POLICY portfolio_read ON public.portfolio_projects FOR SELECT USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=user_id AND p.shared) OR public.has_role(auth.uid(),'admin')); CREATE POLICY portfolio_write ON public.portfolio_projects FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.assessment_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assessment_id text NOT NULL REFERENCES public.assessments(id),question text NOT NULL,options jsonb NOT NULL,correct integer NOT NULL); GRANT SELECT,INSERT,UPDATE,DELETE ON public.assessment_questions TO authenticated; GRANT ALL ON public.assessment_questions TO service_role; ALTER TABLE public.assessment_questions ENABLE ROW LEVEL SECURITY; CREATE POLICY questions_admin ON public.assessment_questions FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin')); INSERT INTO public.assessment_questions(assessment_id,question,options,correct) SELECT a.id,q->>'question',q->'options',(q->>'correct')::integer FROM public.assessments a CROSS JOIN LATERAL jsonb_array_elements(a.questions) q;
CREATE TABLE public.readiness_tasks(id text PRIMARY KEY,title text NOT NULL,url text NOT NULL,official_confirmation boolean NOT NULL DEFAULT false); GRANT SELECT ON public.readiness_tasks TO anon,authenticated; GRANT ALL ON public.readiness_tasks TO service_role; ALTER TABLE public.readiness_tasks ENABLE ROW LEVEL SECURITY; CREATE POLICY tasks_read ON public.readiness_tasks FOR SELECT USING(true); INSERT INTO public.readiness_tasks VALUES('authorization','Work authorization','https://help.unhcr.org/',true),('documentation','Professional documentation','https://help.unhcr.org/',false),('banking','Banking and payment readiness','https://help.unhcr.org/',true),('cv','CV preparation','https://www.ilo.org/',false),('interview','Interview readiness','https://www.ilo.org/',false),('recognition','Credential recognition','https://www.unesco.org/',true),('training','Professional training','https://www.powerlearnprojectafrica.org/',false);
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,message text NOT NULL,read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY notifications_own ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY notifications_update ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid,action text NOT NULL,record_id uuid,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY audit_admin ON public.audit_logs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.audit_review() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(actor_id,action,record_id,details) VALUES(NEW.reviewer_id,'Credential review',NEW.credential_id,jsonb_build_object('decision',NEW.decision,'notes',NEW.notes)); RETURN NEW; END $$; CREATE TRIGGER review_audit AFTER INSERT ON public.credential_reviews FOR EACH ROW EXECUTE FUNCTION public.audit_review();
CREATE FUNCTION public.application_integrity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.talent_id<>OLD.talent_id OR NEW.opportunity_id<>OLD.opportunity_id OR NEW.cover_note<>OLD.cover_note OR NEW.created_at<>OLD.created_at THEN RAISE EXCEPTION 'Only application status can be updated'; END IF; IF NEW.status<>OLD.status THEN INSERT INTO public.notifications(user_id,message) VALUES(NEW.talent_id,'Your application status is now '||NEW.status); INSERT INTO public.audit_logs(actor_id,action,record_id,details) VALUES(auth.uid(),'Application status updated',NEW.id,jsonb_build_object('from',OLD.status,'to',NEW.status)); END IF; RETURN NEW; END $$; CREATE TRIGGER protect_application BEFORE UPDATE ON public.applications FOR EACH ROW EXECUTE FUNCTION public.application_integrity();
CREATE POLICY admin_profiles_update ON public.profiles FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_assessment_write ON public.assessments FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_mentor_write ON public.mentors FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin')); GRANT INSERT,UPDATE,DELETE ON public.assessments,public.mentors TO authenticated;
CREATE POLICY admin_requests_update ON public.mentorship_requests FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin')); GRANT UPDATE ON public.mentorship_requests TO authenticated;
CREATE INDEX credentials_owner_idx ON public.credentials(user_id); CREATE INDEX reviews_credential_idx ON public.credential_reviews(credential_id); CREATE INDEX portfolio_owner_idx ON public.portfolio_projects(user_id); CREATE INDEX notification_user_idx ON public.notifications(user_id);